"""Experimental corner-local sampling with reserved short lead intervals.

Keep the dominant arc's existing polygonal samples. A short secondary arc
occupies a lead reservation instead of reallocating all lead rows. This is
only a station proposal: the complete sampled-curb and surface guards apply.
Optional compact single-arc allocation preserves the reference arc samples.
The local shallow-arc branch resamples the original analytic side and
requires the caller's complete boundary comparison at the unchanged limit.
"""
import bpy
from . import curved_quad_patch_nodes as four
from . import curved_continuation_nodes as continuation

c = four.c


def build(*,balanced_leads=False,fixed_leads=False,blend_stations=False,compact_single_arcs=False,local_shallow_arcs=False):
    if balanced_leads and fixed_leads:raise ValueError('Select one lead allocation rule')
    name = 'Prochitecture Streets / Reserved lead contact stations v5'
    if balanced_leads:name+=' / Stable weighted leads v2'
    if fixed_leads:name+=' / Fixed equal lead rows v1'
    if blend_stations:name+=' / Bounded station movement v1'
    if compact_single_arcs:name+=' / Compact single-arc lead rows v1'
    if local_shallow_arcs:name+=' / Local shallow rows v1'
    if name in bpy.data.node_groups: return bpy.data.node_groups[name]
    g = c.Graph(name)
    for s in four.stations().interface.items_tree:
        if s.item_type == 'SOCKET':
            g.socket(s.name,s.socket_type,s.in_out,default=getattr(s,'default_value',None))
    for key in ('Corners','Mouths'): g.socket(key,'NodeSocketGeometry')
    if blend_stations:g.socket('Blend','NodeSocketFloat',default=1.)
    inp=g.node('NodeGroupInput'); out=g.node('NodeGroupOutput')
    owner=c.V(g,inp.outputs['Index']); index=c.V(g,g.node('GeometryNodeInputIndex').outputs[0])
    corners=inp.outputs['Corners']; mouths=inp.outputs['Mouths']; plan=inp.outputs['Plan']
    read=lambda key,kind='FLOAT':c._read(g,corners,key,owner,kind)
    saved=g.node('GeometryNodeInputNamedAttribute'); saved.data_type='BOOLEAN'
    saved.inputs['Name'].default_value='st_cg_analytic_break'
    analytic=c._store(g,inp.outputs['Depths'],'st_cg_break',c.choose(g,saved.outputs['Exists'],
        saved.outputs['Attribute'],c.named(g,'st_cg_break','BOOLEAN'),'BOOLEAN'),'BOOLEAN')
    knots=four._knots(g,analytic,owner)
    length=c._read(g,plan,'st_cq_length',owner)
    cell=g.math('MAXIMUM',c.V(g,inp.outputs['Cell Size']),.02)
    following=c._read(g,knots,'st_cg_t',g.math('MINIMUM',index+1.,c._count(g,knots)-1.))
    base=c._stat(g,knots,g.math('CEIL',g.math('MAXIMUM',0.,following-c.named(g,'st_cg_t'))*length/cell),'Sum')
    reference=g.node('GeometryNodeGroup','Original samples at the reserved common count')
    reference.node_tree=four.stations()
    for key in ('Index','Cell Size','Input Valid'):g.bind(inp.outputs[key],reference.inputs[key])
    g.bind(analytic,reference.inputs['Depths'])
    g.bind(c._store(g,plan,'st_cq_base',base,'INT'),reference.inputs['Plan'])
    nxt=g.math('MODULO',owner+1.,c._count(g,mouths))
    la=c._read(g,mouths,'st_cj_parameter',owner)-read('st_cc_sa')
    lb=c._read(g,mouths,'st_cj_parameter',nxt)-read('st_cc_sb')
    arc=continuation.length(g,corners,owner)
    total=la+arc+lb
    radius=read('st_cc_radius'); wa=g.math('ABSOLUTE',read('st_cc_sweep')); wb=g.math('ABSOLUTE',read('st_ct_sweep_b'))
    paired=g.math('COMPARE',read('st_ct_kind','INT'),2.)
    ordinary=g.math('COMPARE',read('st_ct_kind','INT'),0.)
    first_main=g.math('MAXIMUM',1.-paired,1.-g.math('GREATER_THAN',wb,wa))
    a=la/total; b=(la+arc)/total; joint=(la+radius*wa)/total
    main_a=c.choose(g,first_main,a,joint)
    main_b=c.choose(g,paired*first_main,joint,b)
    distance=g.math('MINIMUM',.05*cell,.5*g.math('SQRT',radius*5e-5))
    left=g.math('MAXIMUM',0.,g.math('MINIMUM',a,main_a-distance/total))
    right=g.math('MINIMUM',1.,g.math('MAXIMUM',b,main_b+distance/total))
    t=c.named(g,'st_cq_t')
    inside=c._select(g,reference.outputs['Geometry'],g.math('GREATER_THAN',t,main_a+1e-8)*
                     g.math('LESS_THAN',t,main_b-1e-8))
    minor_a=c._select(g,reference.outputs['Geometry'],g.math('GREATER_THAN',t,a+1e-8)*
                      g.math('LESS_THAN',t,main_a-1e-8))
    minor_b=c._select(g,reference.outputs['Geometry'],g.math('GREATER_THAN',t,main_b+1e-8)*
                      g.math('LESS_THAN',t,b-1e-8))
    core=four.boundary._join(g,minor_a,c._store(g,c._line(g,1),'st_cq_t',main_a),inside,
                            c._store(g,c._line(g,1),'st_cq_t',main_b),minor_b)
    count=c._read(g,plan,'st_cq_count',owner,'INT'); core_count=c._count(g,core)
    spare=count-(core_count-1.)-2.
    nl=g.math('MINIMUM',spare-1.,g.math('MAXIMUM',1.,g.math('FLOOR',spare*left/g.math('MAXIMUM',left+1.-right,1e-12)+.5)))
    if balanced_leads:
        # Keep length-proportional allocation for unequal leads. Quarter-row
        # rounding places both integer and half-integer symmetry away from a
        # quota boundary; equal/near-equal leads cannot swap an odd spare row
        # merely through float noise. Other quota transitions remain discrete.
        quota=spare*left/g.math('MAXIMUM',left+1.-right,1e-12)
        nl=g.math('MINIMUM',spare-1.,g.math('MAXIMUM',1.,g.math('FLOOR',quota+.25)))
    if fixed_leads:nl=g.math('FLOOR',spare*.5)
    nr=spare-nl
    first=left*index/g.math('MAXIMUM',nl,1.)
    middle=c._read(g,core,'st_cq_t',g.math('MAXIMUM',0.,g.math('MINIMUM',core_count-1.,index-nl-1.)))
    last=right+(1.-right)*(index-nl-core_count-1.)/g.math('MAXIMUM',nr,1.)
    t=c.choose(g,1.-g.math('GREATER_THAN',index,nl),first,
        c.choose(g,1.-g.math('GREATER_THAN',index,nl+core_count),middle,last))
    # These rows are the two exact mouth endpoints, not extrapolation queries.
    # right+(1-right)*nr/nr can round one float32 ULP above 1 and reject the
    # entire valid entrance chart. Pin identities; do not relax chart bounds.
    t=c.choose(g,g.math('COMPARE',index,0.),0.,
        c.choose(g,g.math('COMPARE',index,count),1.,t))
    geometry=c._store(g,c._line(g,count+1.),'st_cq_t',t)
    previous=c._read(g,geometry,'st_cq_t',g.math('MAXIMUM',0.,index-1.))
    reservation_valid=g.math('GREATER_THAN',spare,1.5)
    for delta in (left,main_a-left,main_b-main_a,right-main_b,1.-right):
        reservation_valid*=g.math('GREATER_THAN',delta,1e-8)
    reservation_valid*=c._stat(g,geometry,c.choose(g,g.math('LESS_THAN',index,.5),True,
        g.math('GREATER_THAN',c.named(g,'st_cq_t')-previous,1e-8),'BOOLEAN'))
    valid=c.V(g,reference.outputs['Valid'])*reservation_valid
    valid*=g.math('MAXIMUM',ordinary,paired*read('st_cj_contact_transition','BOOLEAN'))
    # A straight continuation or shared source knot has no circular segment
    # around which to reserve leads. Keep its original station list at the
    # same common count. This is a per-side construction, not whole-surface
    # fallback; the enclosing boundary and surface checks still apply.
    no_arc=g.math('MAXIMUM',g.math('COMPARE',read('st_ct_kind','INT'),1.),
                  g.math('COMPARE',read('st_ct_kind','INT'),3.))
    # Compact single-arc corners need not spend extra rows on two reservations:
    # their unmodified sampling has no moving internal two-arc join. Retain it
    # when the reservations do not fit. A two-arc proposal still rejects.
    keep_reference=g.math('MAXIMUM',no_arc,ordinary*(1.-reservation_valid))
    geometry=c.choose(g,keep_reference,reference.outputs['Geometry'],geometry,'GEOMETRY')
    valid=c.choose(g,keep_reference,reference.outputs['Valid'],valid,'BOOLEAN')
    if compact_single_arcs:
        # A single arc has no moving internal circle join. Preserve its exact
        # reference samples but assign spare rows consistently to the two
        # leads. The previous fallback used ceil(lead/cell), so a 0.7 m lead
        # growing by millimetres could shift every arc row by one identity.
        # No circle samples are moved or removed; the enclosing complete
        # boundary and cell-shape guards still admit or reject this proposal.
        spare_compact=count-(core_count-1.)
        left_count=g.math('FLOOR',spare_compact*.5)
        right_count=spare_compact-left_count
        begin=a*index/g.math('MAXIMUM',left_count,1.)
        arc_t=c._read(g,core,'st_cq_t',g.math('MAXIMUM',0.,
            g.math('MINIMUM',core_count-1.,index-left_count)))
        end=b+(1.-b)*(index-left_count-core_count+1.)/g.math('MAXIMUM',right_count,1.)
        compact_t=c.choose(g,g.math('LESS_THAN',index,left_count),begin,
            c.choose(g,g.math('LESS_THAN',index,left_count+core_count),arc_t,end))
        compact_t=c.choose(g,g.math('COMPARE',index,0.),0.,
            c.choose(g,g.math('COMPARE',index,count),1.,compact_t))
        compact=c._store(g,c._line(g,count+1.),'st_cq_t',compact_t)
        before=c._read(g,compact,'st_cq_t',g.math('MAXIMUM',0.,index-1.))
        eligible=ordinary*(1.-reservation_valid)*g.math('GREATER_THAN',spare_compact,1.5)
        eligible*=g.math('GREATER_THAN',a,1e-8)*g.math('LESS_THAN',b,1.-1e-8)
        eligible*=c._stat(g,compact,c.choose(g,g.math('LESS_THAN',index,.5),True,
            g.math('GREATER_THAN',c.named(g,'st_cq_t')-before,1e-8),'BOOLEAN'))
        geometry=c.choose(g,eligible,compact,geometry,'GEOMETRY')
        valid=c.choose(g,eligible,reference.outputs['Valid'],valid,'BOOLEAN')
    if balanced_leads or fixed_leads:
        # No extra row can swap between equal-length leads. A genuinely
        # straight continuation also needs no internal contact breakpoint.
        # Curved source pieces are still checked by the complete 50 um bound.
        straight=g.math('COMPARE',read('st_ct_kind','INT'),1.)
        uniform=c._store(g,c._line(g,count+1.),'st_cq_t',index/g.math('MAXIMUM',count,1.))
        geometry=c.choose(g,straight,uniform,geometry,'GEOMETRY')
    if blend_stations:
        # Limit movement from the original polygon's station list. The caller
        # measures the complete proposal, then checks the resulting polygon
        # against the unchanged bound; this interpolation is not a certificate.
        a=c._read(g,reference.outputs['Geometry'],'st_cq_t',index)
        b=c.named(g,'st_cq_t')
        weight=c.bounded(g,c.V(g,inp.outputs['Blend']))
        t=c.choose(g,g.math('GREATER_THAN',weight,1.-1e-7),b,a+(b-a)*weight)
        t=c.choose(g,g.math('COMPARE',index,0.),0.,c.choose(g,g.math('COMPARE',index,count),1.,t))
        geometry=c._store(g,geometry,'st_cq_t',t)
        previous=c._read(g,geometry,'st_cq_t',g.math('MAXIMUM',0.,index-1.))
        valid*=g.math('COMPARE',c._count(g,reference.outputs['Geometry']),c._count(g,geometry))
        valid*=c._stat(g,geometry,c.choose(g,g.math('LESS_THAN',index,.5),True,
            g.math('GREATER_THAN',c.named(g,'st_cq_t')-previous,1e-8),'BOOLEAN'))
    if local_shallow_arcs:
        # A tiny one- or two-arc contact can create almost coincident rows.
        # Sample the same analytic side uniformly after the junction-wide
        # blend heuristic, which can suppress a useful local proposal.
        # These thresholds only choose a mesh;
        # the caller's complete 50 um boundary bound still checks that actual
        # mesh, alongside all shape, seam, profile and footprint guards.
        eligible=g.math('MAXIMUM',ordinary,paired)*g.math('LESS_THAN',wa+wb,.02)
        eligible*=g.math('LESS_THAN',arc,.1*c.V(g,inp.outputs['Cell Size']))
        eligible*=g.math('GREATER_THAN',la,0.)*g.math('GREATER_THAN',lb,0.)
        uniform=c._store(g,c._line(g,count+1.),'st_cq_t',index/g.math('MAXIMUM',count,1.))
        geometry=c.choose(g,eligible,uniform,geometry,'GEOMETRY')
        valid=c.choose(g,eligible,reference.outputs['Valid'],valid,'BOOLEAN')
    g.bind(geometry,out.inputs['Geometry']); g.bind(valid,out.inputs['Valid'])
